import backtrader as bt


class RiskOnRiskOff(bt.Strategy):
    def __init__(self):
        self.sma = bt.indicators.SimpleMovingAverage(self.data.close, period=200)
        self.crossover = bt.indicators.CrossOver(self.data.close, self.sma)
        self.order = None

    def notify_order(self, order):
        if order.status in [order.Completed, order.Canceled, order.Margin, order.Rejected]:
            self.order = None

    def next(self):
        if self.order:
            return

        if not self.position:
            if self.crossover[0] > 0:
                self.order = self.order_target_percent(target=1.0)
        else:
            if self.crossover[0] < 0:
                self.order = self.close()
